CREATE TABLE `monitoring_period_closure_references` (`monitoring_period_closure_reference_id` BIGINT NOT NULL AUTO_INCREMENT,`monitoring_period_id` BIGINT NOT NULL,`kpi_pool_id` BIGINT NOT NULL,`pool_input_period_id` BIGINT NOT NULL,`period_key` VARCHAR(30) NOT NULL,`closure_type` VARCHAR(40) NOT NULL,`closed_at` DATETIME(3) NOT NULL,`source_version` INT UNSIGNED NOT NULL,`source_event_id` CHAR(36) NOT NULL,`created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`monitoring_period_closure_reference_id`),UNIQUE INDEX `uq_mpcr_monitoring_period` (`monitoring_period_id`),UNIQUE INDEX `uq_mpcr_source_event` (`source_event_id`),UNIQUE INDEX `uq_mpcr_pool_period` (`kpi_pool_id`,`pool_input_period_id`),INDEX `ix_mpcr_pool_period_key` (`kpi_pool_id`,`period_key`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
CREATE TABLE `processed_events` (`event_id` CHAR(36) NOT NULL,`event_type` VARCHAR(120) NOT NULL,`subject` VARCHAR(200) NOT NULL,`aggregate_id` VARCHAR(100) NULL,`source_service` VARCHAR(100) NULL,`processed_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY (`event_id`),INDEX `ix_processed_events_type` (`event_type`,`processed_at`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
